<style>
:root {
--bg: #090a0f;
--card-bg: rgba(22, 24, 35, 0.75);
--card-border: rgba(255, 255, 255, 0.08);
--card-hover: rgba(255, 255, 255, 0.18);
--accent: #7c3aed;
--accent-glow: rgba(124, 58, 237, 0.38);
--pink: #ff2a7a;
--text-main: #f8fafc;
--text-muted: #94a3b8;
--radius: 14px;
--btn-radius: 10px;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
html { scroll-behavior: smooth; }

body {
background-color: var(--bg);
color: var(--text-main);
font-family: 'Plus Jakarta Sans', sans-serif;
line-height: 1.6;
overflow-x: hidden;
background-image:
radial-gradient(circle at 15% 10%, rgba(124, 58, 237, 0.16), transparent 40%),
radial-gradient(circle at 85% 25%, rgba(255, 42, 122, 0.1), transparent 45%),
radial-gradient(circle at 50% 70%, rgba(6, 182, 212, 0.06), transparent 50%);
background-attachment: fixed;
}

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* Topo / Header */
header {
position: sticky; top: 0; z-index: 200;
backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px);
background: rgba(9, 10, 15, 0.92);
border-bottom: 1px solid var(--card-border);
padding: 14px 0;
}

.nav-inner { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.brand { display: flex; align-items: center; gap: 12px; text-decoration: none; color: var(--text-main); min-width: 0; }

.brand-avatar-box {
width: 44px; height: 44px; border-radius: 12px;
overflow: hidden; flex-shrink: 0; position: relative;
background: linear-gradient(135deg, var(--accent), var(--pink));
display: flex; align-items: center; justify-content: center;
border: 1.5px solid rgba(255, 255, 255, 0.15);
box-shadow: 0 4px 12px var(--accent-glow);
}
.brand-avatar-img { width: 100%; height: 100%; object-fit: cover; object-position: center 20%; display: block; }
.brand-avatar-fallback { font-weight: 800; font-size: 1.05rem; color: #fff; }

.brand-info { min-width: 0; }
.brand-info h1 { font-size: 1.08rem; font-weight: 700; letter-spacing: -0.3px; white-space: nowrap; }
.brand-info p { font-size: 0.78rem; color: var(--text-muted); }

.nav-actions { display: flex; align-items: center; gap: 12px; position: relative; flex-shrink: 0; }
.badge-status {
display: inline-flex; align-items: center; gap: 6px;
padding: 6px 12px; background: rgba(16, 185, 129, 0.1);
border: 1px solid rgba(16, 185, 129, 0.25); color: #34d399;
font-size: 0.78rem; font-weight: 600; border-radius: 8px;
white-space: nowrap;
}
.status-dot {
width: 7px; height: 7px; background: #10b981; border-radius: 50%;
box-shadow: 0 0 10px #10b981; animation: pulse 2s infinite;
}
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }

/* Dropdown Fale Comigo */
.contact-dropdown-container { position: relative; display: inline-block; }

.btn {
display: inline-flex; align-items: center; justify-content: center; gap: 8px;
padding: 10px 18px; border-radius: var(--btn-radius); font-weight: 600; font-size: 0.88rem;
text-decoration: none; transition: all 0.25s ease; cursor: pointer; border: none;
white-space: nowrap; font-family: inherit;
}
.btn-primary {
background: linear-gradient(135deg, var(--accent), #6d28d9);
color: #fff; box-shadow: 0 4px 18px var(--accent-glow);
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(124, 58, 237, 0.5); }
.btn-secondary {
background: rgba(255, 255, 255, 0.05); border: 1px solid var(--card-border); color: var(--text-main);
}
.btn-secondary:hover { background: rgba(255, 255, 255, 0.1); border-color: rgba(255, 255, 255, 0.2); }

.dropdown-menu {
position: absolute;
top: calc(100% + 8px);
right: 0;
background: #12141f;
border: 1px solid rgba(124, 58, 237, 0.4);
border-radius: 12px;
padding: 8px;
min-width: 250px;
max-width: calc(100vw - 28px);
box-shadow: 0 18px 40px rgba(0, 0, 0, 0.75), 0 0 25px rgba(124, 58, 237, 0.25);
display: none;
flex-direction: column;
gap: 4px;
z-index: 300;
backdrop-filter: blur(20px);
}
.dropdown-menu.show { display: flex; animation: dropFade 0.2s ease; }
@keyframes dropFade { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: translateY(0); } }

.dropdown-item {
display: flex; align-items: center; gap: 12px;
padding: 10px 14px; color: #e2e8f0; text-decoration: none;
font-size: 0.86rem; font-weight: 600; border-radius: 8px;
transition: all 0.2s ease;
}
.dropdown-item:hover { background: rgba(124, 58, 237, 0.22); color: #fff; transform: translateX(4px); }
.dropdown-icon { font-size: 1.2rem; width: 26px; text-align: center; flex-shrink: 0; }

/* Barra de Abas */
.tabs-bar {
margin: 28px 0 22px;
border-bottom: 1px solid var(--card-border);
display: flex; gap: 10px;
overflow-x: auto; padding-bottom: 6px;
-webkit-overflow-scrolling: touch; scrollbar-width: none;
}
.tabs-bar::-webkit-scrollbar { display: none; }

.tab-btn {
background: rgba(255, 255, 255, 0.03);
border: 1px solid transparent;
color: var(--text-muted);
font-family: 'Plus Jakarta Sans', sans-serif;
font-size: 0.95rem; font-weight: 600;
padding: 10px 22px; border-radius: var(--btn-radius);
cursor: pointer; transition: all 0.2s ease;
white-space: nowrap; flex-shrink: 0;
}
.tab-btn:hover { color: #fff; background: rgba(255, 255, 255, 0.06); }
.tab-btn.active {
color: #fff; background: var(--accent);
border-color: rgba(255, 255, 255, 0.2); font-weight: 700;
box-shadow: 0 4px 16px rgba(124, 58, 237, 0.4);
}

.tab-content { display: none; animation: fadeIn 0.3s ease; padding-bottom: 70px; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

/* Hero Pitch */
.hero-pitch-card {
background: linear-gradient(135deg, rgba(124, 58, 237, 0.18), rgba(255, 42, 122, 0.08));
border: 1px solid rgba(124, 58, 237, 0.35);
border-radius: var(--radius);
padding: 32px 28px; margin-bottom: 20px;
}
.pitch-tag {
font-family: 'Space Grotesk', sans-serif;
font-size: 0.78rem; font-weight: 700; text-transform: uppercase;
letter-spacing: 2px; color: #c4b5fd; margin-bottom: 8px; display: inline-block;
}
.pitch-title { font-size: 2.1rem; font-weight: 800; line-height: 1.22; margin-bottom: 12px; letter-spacing: -0.6px; }
.pitch-text { font-size: 1.02rem; color: #e2e8f0; max-width: 860px; line-height: 1.55; margin-bottom: 18px; }
.learn-more-link {
display: inline-flex; align-items: center; gap: 6px;
color: #a78bfa; font-size: 0.9rem; font-weight: 700; text-decoration: none;
transition: all 0.2s ease; margin-bottom: 20px;
}
.learn-more-link:hover { color: #fff; transform: translateX(3px); }
.hero-actions-bar { display: flex; gap: 10px; flex-wrap: wrap; }

/* Faixa de Marcas (Marquee) */
.brands-showcase-box {
background: var(--card-bg); border: 1px solid var(--card-border);
border-radius: var(--radius); padding: 18px 22px; margin-bottom: 20px;
}
.brands-showcase-header {
display: flex; justify-content: space-between; align-items: center;
margin-bottom: 14px; padding-bottom: 8px;
border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.brands-showcase-header h4 { font-size: 0.78rem; font-weight: 800; text-transform: uppercase; letter-spacing: 1.2px; color: #c4b5fd; }
.brands-showcase-header span { font-size: 0.75rem; color: var(--text-muted); }

.marquee-container {
overflow: hidden; position: relative; width: 100%;
mask-image: linear-gradient(to right, transparent, black 5%, black 95%, transparent);
-webkit-mask-image: linear-gradient(to right, transparent, black 5%, black 95%, transparent);
}
.marquee-track { display: flex; gap: 10px; width: max-content; animation: marqueeScroll 28s linear infinite; }
.marquee-track:hover { animation-play-state: paused; }
@keyframes marqueeScroll { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }

.brand-pill {
display: inline-flex; align-items: center; padding: 8px 16px;
background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08);
border-radius: 8px; font-size: 0.84rem; font-weight: 600; color: #e2e8f0;
transition: all 0.2s ease; white-space: nowrap; flex-shrink: 0;
}
.brand-pill:hover { background: rgba(124, 58, 237, 0.25); border-color: rgba(124, 58, 237, 0.6); color: #fff; }

/* Números de Impacto */
.big-stats-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; margin: 20px 0 28px; }
.big-stat-box {
background: var(--card-bg); border: 1px solid var(--card-border);
border-radius: var(--radius); padding: 20px 14px; text-align: center;
transition: all 0.3s ease; position: relative; overflow: hidden;
}
.big-stat-box::before {
content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px;
background: linear-gradient(90deg, var(--accent), var(--pink));
}
.big-stat-box:hover { border-color: var(--card-hover); transform: translateY(-2px); }
.big-stat-num {
font-family: 'Space Grotesk', sans-serif; font-size: 2.3rem; font-weight: 800; line-height: 1;
margin-bottom: 6px; background: linear-gradient(180deg, #ffffff 40%, #cbd5e1 100%);
-webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.big-stat-label { font-size: 0.76rem; color: var(--text-muted); font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }

/* Especialidades */
.section-title { font-size: 1.3rem; font-weight: 800; margin: 28px 0 14px; display: flex; align-items: center; gap: 10px; }
.section-title::before { content: ""; width: 4px; height: 18px; background: var(--accent); border-radius: 4px; display: inline-block; }

.what-i-do-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 16px; margin-bottom: 36px; }
.service-card {
background: var(--card-bg); border: 1px solid var(--card-border);
border-radius: var(--radius); padding: 20px 18px; transition: all 0.3s ease;
}
.service-card:hover { border-color: var(--card-hover); transform: translateY(-2px); }
.service-num { font-family: 'Space Grotesk', sans-serif; font-size: 0.8rem; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
.service-title { font-size: 1.05rem; font-weight: 700; color: #fff; margin-bottom: 6px; }
.service-desc { font-size: 0.86rem; color: var(--text-muted); line-height: 1.5; }

/* Trajetória */
.bio-extended-section {
background: rgba(255, 255, 255, 0.02); border: 1px solid var(--card-border);
border-radius: var(--radius); padding: 32px 28px; margin-top: 36px;
}
.bio-extended-section h3 { font-size: 1.35rem; font-weight: 800; margin-bottom: 12px; color: #fff; }
.bio-extended-section p { font-size: 0.95rem; color: #cbd5e1; line-height: 1.65; margin-bottom: 16px; }

.career-timeline { margin-top: 28px; display: flex; flex-direction: column; gap: 16px; }
.career-item {
background: var(--card-bg); border: 1px solid var(--card-border);
border-left: 3px solid var(--accent); border-radius: 10px;
padding: 20px; transition: all 0.25s ease;
}
.career-item:hover { border-color: var(--card-hover); border-left-color: var(--pink); transform: translateX(3px); }
.career-header { display: flex; justify-content: space-between; align-items: baseline; flex-wrap: wrap; gap: 8px; margin-bottom: 6px; }
.career-role { font-size: 1.05rem; font-weight: 700; color: #fff; }
.career-company { color: #c4b5fd; font-weight: 600; font-size: 0.92rem; }
.career-period {
font-family: 'Space Grotesk', sans-serif; font-size: 0.78rem; color: var(--text-muted);
background: rgba(255, 255, 255, 0.05); padding: 3px 8px; border-radius: 6px; font-weight: 600;
}
.career-desc { font-size: 0.88rem; color: #94a3b8; line-height: 1.55; margin-top: 6px; }

.skills-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; margin-top: 24px; }
.skill-box { background: var(--card-bg); border: 1px solid var(--card-border); border-radius: 12px; padding: 18px; }
.skill-box h4 { font-size: 0.95rem; margin-bottom: 10px; color: #fff; }
.skill-list { list-style: none; }
.skill-list li { font-size: 0.84rem; color: var(--text-muted); margin-bottom: 6px; }
.skill-list li::before { content: "•"; color: var(--accent); margin-right: 6px; font-weight: bold; }

/* =======================================================
PLAYERS DE VÍDEO
O iframe é sempre posicionado no canto superior esquerdo.
No mobile, o JavaScript (fitVideo) renderiza o player do
Drive em tamanho "desktop" e reduz com scale(), para que
os controles fiquem proporcionais ao vídeo.
======================================================= */
.video-wrapper,
.video-wrapper-led {
position: relative;
width: 100%;
overflow: hidden;
background: #000;
margin: 0 auto 14px auto;
}
.video-wrapper iframe,
.video-wrapper-led iframe {
position: absolute;
top: 0;
left: 0;
width: 100%;
height: 100%;
border: 0;
transform-origin: 0 0;
}

/* Player nativo (vídeos do Drive): timeline embaixo, sem escurecer */
.video-wrapper video,
.video-wrapper-led video {
position: absolute;
inset: 0;
width: 100%;
height: 100%;
object-fit: contain;
background: #000;
display: block;
}

/* 16:9 padrão */
.video-wrapper {
aspect-ratio: 16 / 9;
border-radius: 12px;
border: 1px solid rgba(255, 255, 255, 0.1);
box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
}

/* Vertical 9:16 */
.video-wrapper.portrait {
max-width: 290px;
aspect-ratio: 9 / 16;
margin: 0 auto 16px auto;
border-radius: 14px;
border: 1px solid rgba(124, 58, 237, 0.4);
box-shadow: 0 8px 24px rgba(0, 0, 0, 0.55);
}

/* Telão LED ultra-wide */
.video-wrapper-led {
aspect-ratio: 21 / 9;
border-radius: 10px;
border: 1px solid rgba(124, 58, 237, 0.4);
box-shadow: 0 6px 24px rgba(0, 0, 0, 0.6), 0 0 20px rgba(124, 58, 237, 0.25);
}

/* Bento Grid */
.bento-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 18px; margin-top: 14px; margin-bottom: 24px; }
.bento-card {
background: var(--card-bg); border: 1px solid var(--card-border);
border-radius: var(--radius); padding: 22px;
position: relative; overflow: hidden;
transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
display: flex; flex-direction: column; justify-content: space-between;
min-width: 0;
}
/* Garante que os blocos internos ocupem toda a largura (evita vídeo descentralizado) */
.bento-card > div { width: 100%; }
.bento-card:hover { border-color: var(--card-hover); transform: translateY(-3px); box-shadow: 0 12px 26px rgba(0, 0, 0, 0.4); }

.bento-card.card-vertical { text-align: center; align-items: center; justify-content: flex-start; }
.bento-card.card-vertical .card-tag { margin-left: auto; margin-right: auto; }
.bento-card.card-vertical .card-title,
.bento-card.card-vertical .card-desc { text-align: center; width: 100%; }
.bento-card.card-vertical .card-meta,
.bento-card.card-vertical .card-links { justify-content: center; width: 100%; }

.col-12 { grid-column: span 12; }
.col-7 { grid-column: span 7; }
.col-6 { grid-column: span 6; }
.col-5 { grid-column: span 5; }

.card-tag {
display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px;
border-radius: 6px; font-size: 0.72rem; font-weight: 700; text-transform: uppercase;
margin-bottom: 12px; width: fit-content;
background: rgba(255, 255, 255, 0.06); color: #e2e8f0; border: 1px solid rgba(255, 255, 255, 0.12);
}
.tag-3d { background: rgba(139, 92, 246, 0.15); color: #c4b5fd; border: 1px solid rgba(139, 92, 246, 0.3); }
.tag-tech { background: rgba(6, 182, 212, 0.15); color: #67e8f9; border: 1px solid rgba(6, 182, 212, 0.3); }
.tag-ai { background: rgba(255, 42, 122, 0.15); color: #fda4af; border: 1px solid rgba(255, 42, 122, 0.3); }
.tag-cutout { background: rgba(245, 158, 11, 0.15); color: #fcd34d; border: 1px solid rgba(245, 158, 11, 0.3); }
.tag-led { background: rgba(168, 85, 247, 0.2); color: #e9d5ff; border: 1px solid rgba(168, 85, 247, 0.45); }
.tag-vert { background: rgba(236, 72, 153, 0.15); color: #f472b6; border: 1px solid rgba(236, 72, 153, 0.35); }

.card-title { font-size: 1.2rem; font-weight: 700; margin-bottom: 8px; color: #fff; line-height: 1.35; }
.card-desc { font-size: 0.88rem; color: var(--text-muted); margin-bottom: 16px; line-height: 1.55; }
.card-meta {
display: flex; flex-wrap: wrap; gap: 6px; margin-top: auto;
padding-top: 12px; border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.pill { font-size: 0.74rem; padding: 5px 9px; border-radius: 6px; background: rgba(255, 255, 255, 0.04); color: #94a3b8; }
.card-links { display: flex; gap: 8px; margin-top: 14px; flex-wrap: wrap; }
.card-link-btn {
font-size: 0.8rem; font-weight: 600; text-decoration: none; color: #fff;
display: inline-flex; align-items: center; justify-content: center; gap: 6px;
padding: 8px 14px; background: rgba(255, 255, 255, 0.08); border-radius: 8px;
transition: all 0.2s ease;
}
.card-link-btn:hover { background: var(--accent); }
.card-link-btn.btn-highlight {
background: linear-gradient(135deg, rgba(124, 58, 237, 0.4), rgba(255, 42, 122, 0.3));
border: 1px solid rgba(124, 58, 237, 0.5);
}
.card-link-btn.btn-highlight:hover { background: var(--accent); box-shadow: 0 4px 14px rgba(124, 58, 237, 0.4); }

/* Carrosséis */
.slider-section {
background: var(--card-bg); border: 1px solid var(--card-border);
border-radius: var(--radius); padding: 28px; margin-bottom: 32px; position: relative;
}
.slider-header {
display: flex; justify-content: space-between; align-items: flex-start;
margin-bottom: 18px; flex-wrap: wrap; gap: 12px;
border-bottom: 1px solid rgba(255, 255, 255, 0.06); padding-bottom: 14px;
}
.slider-title { font-size: 1.35rem; font-weight: 800; color: #fff; display: flex; align-items: center; gap: 8px; }
.slider-category-desc { font-size: 0.88rem; color: var(--text-muted); margin-top: 4px; max-width: 760px; }
.slider-counter {
font-family: 'Space Grotesk', sans-serif; font-size: 0.88rem; font-weight: 700;
background: rgba(124, 58, 237, 0.15); border: 1px solid rgba(124, 58, 237, 0.35);
color: #c4b5fd; padding: 6px 14px; border-radius: 8px; white-space: nowrap;
}

.slider-stage { max-width: 980px; margin: 0 auto; }
.slider-video-meta { margin-top: 14px; text-align: center; }
.slider-v-title { font-size: 1.25rem; font-weight: 800; color: #fff; margin-bottom: 6px; }
.slider-v-desc { font-size: 0.92rem; color: #cbd5e1; line-height: 1.5; max-width: 740px; margin: 0 auto 8px; }
.slider-v-impact {
font-size: 0.85rem; color: #34d399; font-weight: 600; background: rgba(16, 185, 129, 0.1);
border: 1px solid rgba(16, 185, 129, 0.25); display: inline-block; padding: 4px 12px;
border-radius: 6px; margin-bottom: 10px;
}

.slider-dots-container {
display: flex; align-items: center; gap: 7px;
margin: 16px auto 14px; width: fit-content; max-width: 90%;
overflow-x: auto; padding: 6px 12px;
scrollbar-width: none; -webkit-overflow-scrolling: touch;
}
.slider-dots-container::-webkit-scrollbar { display: none; }
.slider-dot {
width: 8px; height: 8px; border-radius: 50%;
background: rgba(255, 255, 255, 0.22); cursor: pointer;
transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
