<script>
// Menu Dropdown Fale Comigo
function toggleContactDropdown(event) {
event.stopPropagation();
document.getElementById('contactMenu').classList.toggle('show');
}

document.addEventListener('click', function () {
const menu = document.getElementById('contactMenu');
if (menu && menu.classList.contains('show')) menu.classList.remove('show');
});

// Troca de Abas
function switchTab(tabId, buttonElement) {
document.querySelectorAll('.tab-content').forEach(tab => tab.classList.remove('active'));
document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
document.getElementById(tabId).classList.add('active');
buttonElement.classList.add('active');
// Pausa vídeos das abas que saíram de vista
document.querySelectorAll('.tab-content:not(.active) video').forEach(v => v.pause());
}

// ============================================
// AJUSTE DO PLAYER DO GOOGLE DRIVE
// O player do Drive tem botões de tamanho fixo. Em telas pequenas,
// eles ficavam enormes e empurravam o vídeo. Aqui o iframe é
// renderizado numa largura "virtual" maior e reduzido com scale(),
// para que vídeo e controles encolham na mesma proporção.
// Aumente os números para botões menores; diminua para maiores.
// ============================================
const DRIVE_BASE = { portrait: 360, padrao: 560 };

function fitVideo(box) {
const iframe = box.querySelector('iframe');
if (!iframe) return;
const w = box.clientWidth;
const h = box.clientHeight;
if (!w || !h) return; // aba escondida: ajusta quando aparecer

const isDrive = (iframe.getAttribute('src') || '').includes('drive.google.com');
const base = box.classList.contains('portrait') ? DRIVE_BASE.portrait : DRIVE_BASE.padrao;
const s = isDrive ? Math.min(1, w / base) : 1;

iframe.style.width = (w / s) + 'px';
iframe.style.height = (h / s) + 'px';
iframe.style.transform = s < 1 ? 'scale(' + s + ')' : 'none';
}

// ============================================
// PLAYER NATIVO PARA VÍDEOS DO DRIVE
// Troca o player do Drive pelo player do próprio navegador:
// timeline embaixo e sem a tela escura ao dar play.
// Se o Drive bloquear o arquivo (ex.: vídeos muito grandes),
// volta automaticamente para o player do Drive.
// ============================================
function driveId(url) {
const m = (url || '').match(/\/file\/d\/([^/]+)/);
return m ? m[1] : null;
}

function mountPlayer(box, src, extraClass) {
const old = box.querySelector('iframe, video');
const id = driveId(src);

// YouTube e outros: mantém iframe
if (!id) {
if (old && old.tagName === 'IFRAME') { old.src = src; return; }
const iframe = makeIframe(src, extraClass);
if (old) old.replaceWith(iframe); else box.appendChild(iframe);
return;
}

const video = document.createElement('video');
if (extraClass) video.className = extraClass;
video.controls = true;
video.playsInline = true;
video.preload = 'none';
video.setAttribute('playsinline', '');
video.setAttribute('controlslist', 'nodownload');
video.poster = 'https://drive.google.com/thumbnail?id=' + id + '&sz=w1280';
video.src = 'https://drive.usercontent.google.com/download?id=' + id + '&export=download&confirm=t';

video.addEventListener('error', () => {
const iframe = makeIframe('https://drive.google.com/file/d/' + id + '/preview', extraClass);
video.replaceWith(iframe);
fitVideo(box);
}, { once: true });

if (old) old.replaceWith(video); else box.appendChild(video);
}

function makeIframe(src, extraClass) {
const iframe = document.createElement('iframe');
if (extraClass) iframe.className = extraClass;
iframe.src = src;
iframe.allow = 'autoplay; fullscreen';
iframe.allowFullscreen = true;
iframe.loading = 'lazy';
return iframe;
}

const videoObserver = new ResizeObserver(entries => {
entries.forEach(entry => fitVideo(entry.target));
});

