// Renderiza as bolinhas de todos os carrosséis da categoria
function renderDots(category) {
const slider = slidersData[category];
if (!slider) return;

document.querySelectorAll('.dots-' + category).forEach(container => {
container.innerHTML = '';
slider.items.forEach((_, i) => {
const dot = document.createElement('button');
dot.className = 'slider-dot' + (i === slider.index ? ' active' : '');
dot.title = 'Ir para o item ' + (i + 1);
dot.setAttribute('aria-label', 'Ir para o item ' + (i + 1));
dot.onclick = () => {
slider.index = i;
updateSliderUI(category);
};
container.appendChild(dot);
});
});
}

function updateSliderUI(category) {
const slider = slidersData[category];
if (!slider) return;
const current = slider.items[slider.index];

document.querySelectorAll('.iframe-' + category).forEach(el => {
const box = el.parentElement;
mountPlayer(box, current.src, 'iframe-' + category);
fitVideo(box);
});

document.querySelectorAll('.title-' + category).forEach(el => { el.innerText = current.title; });
document.querySelectorAll('.desc-' + category).forEach(el => { el.innerText = current.desc; });

document.querySelectorAll('.counter-' + category).forEach(el => {
const prefix = category === 'fiocruz' ? 'Episódio' : category === 'enobrecimento' ? 'Acabamento' : 'Vídeo';
el.innerText = prefix + ' ' + (slider.index + 1) + ' de ' + slider.items.length;
});

document.querySelectorAll('.impact-' + category).forEach(el => {
if (current.impact) {
el.innerText = current.impact;
el.style.display = 'inline-block';
} else {
el.style.display = 'none';
}
});

document.querySelectorAll('.link-' + category).forEach(linkBtn => {
if (current.link) linkBtn.href = current.link;
else if (current.yt) linkBtn.href = 'https://www.youtube.com/watch?v=' + current.yt;
});

document.querySelectorAll('.dots-' + category).forEach(dotsContainer => {
dotsContainer.querySelectorAll('.slider-dot').forEach((dot, idx) => {
dot.className = 'slider-dot' + (idx === slider.index ? ' active' : '');
if (idx === slider.index) {
dot.scrollIntoView({ block: 'nearest', inline: 'center', behavior: 'smooth' });
}
});
});
}

function nextSlide(category) {
const slider = slidersData[category];
slider.index = (slider.index + 1) % slider.items.length;
updateSliderUI(category);
}

function prevSlide(category) {
const slider = slidersData[category];
slider.index = (slider.index - 1 + slider.items.length) % slider.items.length;
updateSliderUI(category);
}

// Inicialização (o script está no fim do body, o HTML já existe)
Object.keys(slidersData).forEach(cat => renderDots(cat));

// Converte todos os players do Drive para o player nativo
document.querySelectorAll('.video-wrapper iframe, .video-wrapper-led iframe').forEach(iframe => {
const src = iframe.getAttribute('src');
if (driveId(src)) mountPlayer(iframe.parentElement, src, iframe.className);
});
document.querySelectorAll('.video-wrapper, .video-wrapper-led').forEach(box => videoObserver.observe(box));
</script>

